mapper.update:
UPDATE PARAMETER
	   SET PMCO = #{pmco, jdbcType = VARCHAR}, PMNM = #{pmnm, jdbcType = VARCHAR}
	 WHERE PMST = #{pmst, jdbcType = VARCHAR}
	   AND PMKY = #{pmky, jdbcType = VARCHAR}
	   AND PMCO = #{oldPmco, jdbcType = VARCHAR}

mapper.delete:
DELETE FROM PARAMETER
	 WHERE PMST = #{pmst, jdbcType = VARCHAR}
	   AND PMKY = #{pmky, jdbcType = VARCHAR}
	   AND PMCO = #{pmco, jdbcType = VARCHAR}

mapper.select:
SELECT T.BNK_NO AS bnkNo,BNK_NM AS bnkNm FROM DS_BANK_BNKBASE T  

where T.BNK_NO=#{sp.backNo}

ORDER BY T.DIS_ORDER,T.BNK_NO

SELECT PMST, PMKY, PMCO, PMNM, PMV1, PMV2,PMV3, PMV4, PMV5,INSERTTIMESTAMP,UPDATETIMESTAMP 
FROM PARAMETER 
WHERE PMCO = '******' 
  AND PMKY IN (SELECT PMCO FROM PARAMETER WHERE PMCO <> '******' AND PMST = 'SYSTEM' AND PMKY = 'BUSIMANA') 

	AND  PMST = #{sp.pmst}


	AND  PMKY LIKE CONCAT(CONCAT('%', #{sp.pmky}),'%')


	AND  PMCO =#{sp.qpmco}


	AND  PMCO LIKE CONCAT(CONCAT('%', #{sp.pmco}),'%')


	AND  PMNM LIKE CONCAT(CONCAT('%', #{sp.pmnm}),'%')


	AND  PMNM LIKE CONCAT(CONCAT('%', #{sp.qpmnm}),'%')



	AND  PMNM LIKE CONCAT(CONCAT('%', #{sp.allPmnm}),'%')


	AND  PMKY = #{sp.allPmky}


	AND  PMV1  = #{sp.pmv1}	


	AND  PMV2  = #{sp.pmv2}	

ORDER BY PMST, PMKY, PMCO
